856: 		private static Mutex TryGlobalInstanceNotify(string strBaseName)
857: 		{
858: 			if(strBaseName == null) throw new ArgumentNullException("strBaseName");
859: 
860: 			try
861: 			{
862: 				string strName = "Global\\" + strBaseName;
863: 				string strIdentity = Environment.UserDomainName + "\\" +
864: 					Environment.UserName;
865: 				MutexSecurity ms = new MutexSecurity();
866: 
867: 				MutexAccessRule mar = new MutexAccessRule(strIdentity,
868: 					MutexRights.FullControl, AccessControlType.Allow);
869: 				ms.AddAccessRule(mar);
870: 
871: 				SecurityIdentifier sid = new SecurityIdentifier(
872: 					WellKnownSidType.WorldSid, null);
873: 				mar = new MutexAccessRule(sid, MutexRights.ReadPermissions |
874: 					MutexRights.Synchronize, AccessControlType.Allow);
875: 				ms.AddAccessRule(mar);
876: 
877: 				bool bCreatedNew;
878: 				return new Mutex(false, strName, out bCreatedNew, ms);
879: 			}
880: 			catch(Exception) { } // Windows 9x and Mono 2.0+ (AddAccessRule) throw
881: 
882: 			return null;
883: 		}
