241: 							t = DesktopType.Unity;
242: 						else if(strXdg.Equals("LXDE", sc))
243: 							t = DesktopType.Lxde;
244: 						else if(strXdg.Equals("XFCE", sc))
245: 							t = DesktopType.Xfce;
246: 						else if(strXdg.Equals("MATE", sc))
247: 							t = DesktopType.Mate;
248: 						else if(strXdg.Equals("X-Cinnamon", sc)) // Mint 18.3
249: 							t = DesktopType.Cinnamon;
250: 						else if(strXdg.Equals("Pantheon", sc)) // Elementary OS
251: 							t = DesktopType.Pantheon;
252: 						else if(strXdg.Equals("KDE", sc) || // Mint 16, Kubuntu 17.10
253: 							strGdm.Equals("kde-plasma", sc)) // Ubuntu 12.04
254: 							t = DesktopType.Kde;
255: 						else if(strXdg.Equals("GNOME", sc))
256: 						{
257: 							if(strGdm.Equals("cinnamon", sc)) // Mint 13
258: 								t = DesktopType.Cinnamon;
259: 							else t = DesktopType.Gnome; // Fedora 27
260: 						}
261: 						else if(strXdg.Equals("ubuntu:GNOME", sc))
262: 							t = DesktopType.Gnome;
263: 					}
264: 					catch(Exception) { Debug.Assert(false); }
265: 				}
266: 
267: 				g_otDesktop = t;
268: 			}
