327: 		public static string RunConsoleApp(string strAppPath, string strParams,
328: 			string strStdInput, AppRunFlags f)
329: 		{
330: 			if(strAppPath == null) throw new ArgumentNullException("strAppPath");
331: 			if(strAppPath.Length == 0) throw new ArgumentException("strAppPath");
332: 
333: 			bool bStdOut = ((f & AppRunFlags.GetStdOutput) != AppRunFlags.None);
334: 
335: 			RunProcessDelegate fnRun = delegate()
336: 			{
337: 				Process pToDispose = null;
338: 				try
339: 				{
340: 					ProcessStartInfo psi = new ProcessStartInfo();
341: 
342: 					psi.FileName = strAppPath;
343: 					if(!string.IsNullOrEmpty(strParams)) psi.Arguments = strParams;
344: 
345: 					psi.CreateNoWindow = true;
346: 					psi.WindowStyle = ProcessWindowStyle.Hidden;
347: 					psi.UseShellExecute = false;
348: 
349: 					psi.RedirectStandardOutput = bStdOut;
350: 					if(strStdInput != null) psi.RedirectStandardInput = true;
351: 
352: 					Process p = StartProcessEx(psi);
353: 					pToDispose = p;
354: 
355: 					if(strStdInput != null)
356: 					{
357: 						EnsureNoBom(p.StandardInput);
358: 
359: 						p.StandardInput.Write(strStdInput);
360: 						p.StandardInput.Dispose();
361: 					}
362: 
363: 					string strOutput = string.Empty;
364: 					if(bStdOut) strOutput = p.StandardOutput.ReadToEnd();
365: 
366: 					if((f & AppRunFlags.WaitForExit) != AppRunFlags.None)
367: 						p.WaitForExit();
368: 					else if((f & AppRunFlags.GCKeepAlive) != AppRunFlags.None)
369: 					{
370: 						pToDispose = null; // Thread disposes it
371: 
372: 						Thread th = new Thread(delegate()
373: 						{
374: 							try { p.WaitForExit(); p.Dispose(); }
375: 							catch(Exception) { Debug.Assert(false); }
376: 						});
377: 						th.Start();
378: 					}
379: 
380: 					return strOutput;
381: 				}
382: #if DEBUG
383: 				catch(ThreadAbortException) { }
384: 				catch(Win32Exception exW)
385: 				{
386: 					Debug.Assert((strAppPath == ClipboardU.XSel) &&
387: 						(exW.NativeErrorCode == 2)); // XSel not found
388: 				}
389: 				catch(Exception) { Debug.Assert(false); }
390: #else
391: 				catch(Exception) { }
392: #endif
393: 				finally
394: 				{
395: 					try { if(pToDispose != null) pToDispose.Dispose(); }
396: 					catch(Exception) { Debug.Assert(false); }
397: 				}
398: 
399: 				return null;
400: 			};
401: 
402: 			if((f & AppRunFlags.DoEvents) != AppRunFlags.None)
403: 			{
404: 				List<Form> lDisabledForms = new List<Form>();
405: 				if((f & AppRunFlags.DisableForms) != AppRunFlags.None)
406: 				{
407: 					foreach(Form form in Application.OpenForms)
408: 					{
409: 						if(!form.Enabled) continue;
410: 
411: 						lDisabledForms.Add(form);
412: 						form.Enabled = false;
413: 					}
414: 				}
415: 
416: 				IAsyncResult ar = fnRun.BeginInvoke(null, null);
417: 
418: 				while(!ar.AsyncWaitHandle.WaitOne(0))
419: 				{
420: 					Application.DoEvents();
421: 					Thread.Sleep(2);
422: 				}
423: 
424: 				string strRet = fnRun.EndInvoke(ar);
425: 
426: 				for(int i = lDisabledForms.Count - 1; i >= 0; --i)
427: 					lDisabledForms[i].Enabled = true;
428: 
429: 				return strRet;
430: 			}
431: 
432: 			return fnRun();
433: 		}
