438: 			if(!MonoWorkarounds.IsRequired(1219)) return;
439: 
440: 			try
441: 			{
442: 				Encoding enc = sw.Encoding;
443: 				if(enc == null) { Debug.Assert(false); return; }
444: 				byte[] pbBom = enc.GetPreamble();
445: 				if((pbBom == null) || (pbBom.Length == 0)) return;
446: 
447: 				// For Mono >= 4.0 (using Microsoft's reference source)
448: 				try
449: 				{
450: 					FieldInfo fi = typeof(StreamWriter).GetField("haveWrittenPreamble",
451: 						BindingFlags.Instance | BindingFlags.NonPublic);
