470: 		public static bool TransformKey256(byte[] pbData32, byte[] pbSeed32,
471: 			ulong uRounds)
472: 		{
473: #if KeePassUAP
474: 			return false;
475: #else
476: 			if(pbData32 == null) { Debug.Assert(false); return false; }
477: 			if(pbData32.Length != 32) { Debug.Assert(false); return false; }
478: 			if(pbSeed32 == null) { Debug.Assert(false); return false; }
479: 			if(pbSeed32.Length != 32) { Debug.Assert(false); return false; }
480: 
481: 			if(IsUnix() || !g_bAllowNative) return false;
482: 
483: 			byte[] pbDataL = null, pbDataR = null;
484: 			try
485: 			{
486: 				pbDataL = MemUtil.Mid(pbData32, 0, 16);
487: 				pbDataR = MemUtil.Mid(pbData32, 16, 16);
488: 
489: 				bool bL = false, bR = false;
490: 
491: 				Thread thL = new Thread(new ThreadStart(() => { bL =
492: 					TransformKeyHalf(pbDataL, pbSeed32, uRounds); }));
493: 				Thread thR = new Thread(new ThreadStart(() => { bR =
494: 					TransformKeyHalf(pbDataR, pbSeed32, uRounds); }));
495: 				thL.Start();
496: 				thR.Start();
497: 				thL.Join();
498: 				thR.Join();
499: 
500: 				if(bL && bR)
501: 				{
502: 					Array.Copy(pbDataL, 0, pbData32, 0, 16);
503: 					Array.Copy(pbDataR, 0, pbData32, 16, 16);
504: 					return true;
505: 				}
506: 			}
507: 			catch(Exception) { Debug.Assert(false); }
508: 			finally
509: 			{
510: 				MemUtil.ZeroByteArray(pbDataL);
511: 				MemUtil.ZeroByteArray(pbDataR);
512: 			}
513: 
514: 			return false;
515: 		}
